<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Kanban Board</title>
<style>
  *, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    background: #1a1d23;
    color: #e0e0e0;
    min-height: 100vh;
    padding: 32px 24px;
  }

  h1 {
    text-align: center;
    font-size: 1.6rem;
    font-weight: 600;
    letter-spacing: -0.5px;
    margin-bottom: 32px;
    color: #f0f0f0;
  }

  .board {
    display: flex;
    gap: 24px;
    max-width: 1100px;
    margin: 0 auto;
    align-items: flex-start;
  }

  .column {
    flex: 1;
    background: #23272f;
    border-radius: 12px;
    padding: 16px;
    min-width: 280px;
    display: flex;
    flex-direction: column;
    gap: 4px;
    box-shadow: 0 4px 24px rgba(0,0,0,0.3);
    border: 2px solid transparent;
    transition: border-color 0.2s ease, background 0.2s ease;
  }

  .column.drag-over {
    border-color: #5b8def;
    background: #2a3040;
  }

  .col-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 8px 4px 16px 4px;
  }

  .col-title {
    font-size: 0.85rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 1px;
  }

  #col-todo .col-title { color: #f0a04b; }
  #col-doing .col-title { color: #5b8def; }
  #col-done .col-title { color: #4bc97a; }

  .count {
    background: rgba(255,255,255,0.1);
    border-radius: 999px;
    padding: 2px 10px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #aaa;
  }

  .card-container {
    flex: 1;
    min-height: 40px;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }

  .card {
    background: #2e3340;
    border-radius: 8px;
    padding: 12px 14px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    cursor: grab;
    user-select: none;
    transition: opacity 0.15s ease, transform 0.15s ease, box-shadow 0.15s ease;
    border-left: 4px solid #5b8def;
  }

  .card:active { cursor: grabbing; }

  .card:hover {
    background: #363c4a;
    transform: translateY(-1px);
    box-shadow: 0 2px 12px rgba(0,0,0,0.25);
  }

  .card.dragging {
    opacity: 0.4;
    transform: scale(0.97);
  }

  #col-doing .card { border-left-color: #f0a04b; }
  #col-done .card { border-left-color: #4bc97a; }

  .card-title {
    flex: 1;
    font-size: 0.9rem;
    line-height: 1.35;
    word-break: break-word;
  }

  .card-del {
    background: none;
    border: none;
    color: #666;
    cursor: pointer;
    font-size: 1.1rem;
    padding: 2px 6px;
    border-radius: 4px;
    line-height: 1;
    transition: color 0.15s, background 0.15s;
    flex-shrink: 0;
  }

  .card-del:hover {
    color: #e74c3c;
    background: rgba(231,76,60,0.15);
  }

  .add-row {
    max-width: 1100px;
    margin: 24px auto 0;
    display: flex;
    gap: 10px;
  }

  #new-card {
    flex: 1;
    padding: 12px 16px;
    border-radius: 8px;
    border: 2px solid #3a3f4c;
    background: #23272f;
    color: #e0e0e0;
    font-size: 0.9rem;
    outline: none;
    transition: border-color 0.2s;
  }

  #new-card:focus { border-color: #5b8def; }

  #add-card {
    padding: 12px 24px;
    border-radius: 8px;
    border: none;
    background: #5b8def;
    color: #fff;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.2s, transform 0.1s;
  }

  #add-card:hover { background: #4a7de0; }
  #add-card:active { transform: scale(0.97); }
</style>
</head>
<body>

<h1>Kanban Board</h1>

<div class="board">
  <div class="column" id="col-todo">
    <div class="col-header">
      <span class="col-title">To Do</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-doing">
    <div class="col-header">
      <span class="col-title">Doing</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>

  <div class="column" id="col-done">
    <div class="col-header">
      <span class="col-title">Done</span>
      <span class="count">0</span>
    </div>
    <div class="card-container"></div>
  </div>
</div>

<div class="add-row">
  <input type="text" id="new-card" placeholder="Add a new card…" autocomplete="off">
  <button id="add-card">Add Card</button>
</div>

<script>
(function () {
  const STORAGE_KEY = 'kanban-board-state';

  function loadState() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY));
    } catch {
      return null;
    }
  }

  function saveState() {
    const state = [];
    document.querySelectorAll('.card').forEach(function (card) {
      state.push({ text: card.querySelector('.card-title').textContent });
    });
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  }

  function updateCounts() {
    var columns = ['col-todo', 'col-doing', 'col-done'];
    columns.forEach(function (id) {
      var col = document.getElementById(id);
      var count = col.querySelectorAll('.card').length;
      col.querySelector('.count').textContent = count;
    });
  }

  function createCardElement(text, columnId) {
    var card = document.createElement('div');
    card.className = 'card';
    card.draggable = true;
    card.dataset.column = columnId;

    var titleSpan = document.createElement('span');
    titleSpan.className = 'card-title';
    titleSpan.textContent = text;

    var delBtn = document.createElement('button');
    delBtn.className = 'card-del';
    delBtn.innerHTML = '&times;';
    delBtn.title = 'Delete card';

    card.appendChild(titleSpan);
    card.appendChild(delBtn);

    delBtn.addEventListener('click', function () {
      card.remove();
      updateCounts();
      saveState();
    });

    return card;
  }

  function addCard(text) {
    if (!text || !text.trim()) return;
    var container = document.querySelector('#col-todo .card-container');
    var card = createCardElement(text.trim(), 'col-todo');
    container.appendChild(card);
    updateCounts();
    saveState();
  }

  // Add button
  document.getElementById('add-card').addEventListener('click', function () {
    var input = document.getElementById('new-card');
    addCard(input.value);
    input.value = '';
    input.focus();
  });

  // Enter key in input
  document.getElementById('new-card').addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addCard(this.value);
      this.value = '';
    }
  });

  // Drag and drop setup on each column's container
  var columns = ['col-todo', 'col-doing', 'col-done'];
  columns.forEach(function (id) {
    var col = document.getElementById(id);
    var container = col.querySelector('.card-container');

    col.addEventListener('dragstart', function (e) {
      if (!e.target.classList.contains('card')) return;
      e.dataTransfer.setData('text/plain', '');
      setTimeout(function () { e.target.classList.add('dragging'); }, 0);
    });

    col.addEventListener('dragend', function (e) {
      if (e.target.classList.contains('card')) {
        e.target.classList.remove('dragging');
      }
    });

    container.addEventListener('dragover', function (e) {
      e.preventDefault();
      col.classList.add('drag-over');
    });

    container.addEventListener('dragleave', function (e) {
      // Only remove if actually leaving the container
      if (!container.contains(e.relatedTarget)) {
        col.classList.remove('drag-over');
      }
    });

    container.addEventListener('drop', function (e) {
      e.preventDefault();
      col.classList.remove('drag-over');

      var draggedCard = null;
      document.querySelectorAll('.card').forEach(function (c) {
        if (c.classList.contains('dragging')) draggedCard = c;
      });

      if (!draggedCard) return;

      // Determine insert position based on Y coordinate
      var cardsInContainer = Array.from(container.querySelectorAll('.card:not(.dragging)'));
      var insertBefore = null;
      var midY = e.clientY;

      for (var i = 0; i < cardsInContainer.length; i++) {
        var rect = cardsInContainer[i].getBoundingClientRect();
        var mid = rect.top + rect.height / 2;
        if (midY < mid) {
          insertBefore = cardsInContainer[i];
          break;
        }
      }

      draggedCard.dataset.column = id;
      if (insertBefore) {
        container.insertBefore(draggedCard, insertBefore);
      } else {
        container.appendChild(draggedCard);
      }

      updateCounts();
      saveState();
    });
  });

  // Restore from localStorage
  var state = loadState();
  if (state && Array.isArray(state)) {
    state.forEach(function (item) {
      addCard(item.text || '');
    });
  }
})();
</script>
</body>
</html>
